            count += 1
            return

        r, c = x_cells[current_idx]
        for neighbor_idx in adj[current_idx]:
            if not ((visited_mask >> neighbor_idx) & 1):
                new_mask = visited_mask | (1 << neighbor_idx)
                dfs(neighbor_idx, new_mask)

    dfs(start_idx, visited_mask)
    total_directed += count

